{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Reopen; propose 50% (AUD 12m) as a negotiating position"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Propose AUD 10,000 de minimis and AUD 120,000 tipping basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek 36 months and delete the all-claims default"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Require a standalone regime: at least AUD 24m cap and six-year survival"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Carve fraud out of caps, thresholds, contractual time bars, disclosure/knowledge exclusions, exclusive remedy and non-reliance"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket/deemed disclosure and require specific, intelligible disclosures"
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete; if unavoidable, narrowly define actual knowledge and require Seller to prove it"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Do not treat consent as obtained: require final consent, evidence of fulfilled conditions and a long-stop termination right"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require simultaneous payoff and effective releases, with prompt registration evidence and no double counting in price adjustments"
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Verify conditions and on-costs, then include a debt-like deduction or Seller-funded reserve plus indemnity without double recovery"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Require payment evidence and confirmatory assignment before Completion, backed by a broader standalone indemnity and appropriate security"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require investigation/remediation covenants and a specific indemnity, with a completion condition if findings justify it"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Verify DD-008/DD-011 and apply consistent debt, working-capital or future operating-cost treatment; control further commitments"
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Redraft clauses 9.3, 12.8, 13 and 20.5 with clear category rules and precedence"
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Reconcile the register with corporate records and capital history, check security interests and obtain title warranties and releases"
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Keep tax and IP expressly open: negotiate tax-specific protection and risk-based IP terms, preserving Ironquay’s separate indemnity"
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

